SELECT ?point ?ts WHERE {
  ?z a brick:Zone ; brick:hasIdentifier/id "Perimeter_mid_ZN_3" .
  ?z brick:hasPoint ?p .
  ?p a brick:Point ; a brick:ZoneAirTemperature .
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  FILTER(str(?label) != "" || true)
}

SELECT ?z ?label WHERE {
  ?z a brick:Zone .
  OPTIONAL { ?z rdfs:label ?label }
  LIMIT 50
}

